# conferências (gera dados/personagem/closure/card.json e o sistema_closure_v1.txt)
d = card["data"]
campos = ["description","personality","scenario","system_prompt","post_history_instructions","first_mes","mes_example"]
texto = "\n".join(d[k] for k in campos)
falas = [l.split(": ",1)[1] for l in mes_example.split("\n") if l.startswith("{{char}}")] + [first_mes]
achou = [t for t in proibidos if re.search(r"(?<!\w)"+re.escape(t)+r"(?!\w)", texto)]
emoji = re.compile("[\U0001F000-\U0001FAFF☀-➿⬀-⯿️]")
print("termos proibidos no card:", achou or "nenhum")
sem_citacao = texto.replace('"!!"', "").replace('"~"', "")
print("'!!' no card (fora da citação \"!!\" das regras):", [l for l in sem_citacao.split("\n") if "!!" in l] or "nenhum")
print("emoji no card:", emoji.findall(texto) or "nenhum")
print("'~~' no card:", "~~" in texto)
print("'kkk' / 'rs' / 'tu' / 'chefe' no card:", re.findall(r"(?i)\bk{3,}\b|\brs(rs)*\b|(?<!\")\btu\b(?!\")|\bchefe\b", texto) or "nenhum")
print("pt-PT no card:", re.findall(r"(?i)\b(estás|fixe|giro|rapariga|ecrã|telemóvel|estou a \w+)\b", texto) or "nenhum")
print("asterisco nas falas dela:", [f for f in falas if "*" in f] or "nenhum")
print(f"'!' nas falas dela: {sum('!' in f for f in falas)} de {len(falas)}; mais de um '!' numa fala:", [f for f in falas if f.count("!") > 1] or "nenhuma")
print("'~' nas falas dela:", sum(f.count("~") for f in falas), "| risada nas falas dela:", sum(len(re.findall(r"(?i)\b(haha|hehe)\b", f)) for f in falas))
inter = [f.split()[0].strip(",.?!") for f in falas]
print("primeira palavra das falas:", inter)
for k in campos:
    print(f"{k}: {len(d[k])} caracteres, ~{len(d[k])//4} tokens")
print("total ~", len(texto)//4, "tokens")
erro = achou or "!!" in sem_citacao or emoji.search(texto) or "~~" in texto or any(f.count("!") > 1 or "*" in f for f in falas)
if erro:
    sys.exit("conferência falhou: card.json não gerado")
json.dump(card, open(D+"card.json","w",encoding="utf-8"), ensure_ascii=False, indent=2)
json.load(open(D+"card.json",encoding="utf-8"))
print("card.json ok")

